#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_heightSource;
uniform float amzp_strength;
uniform float amzp_sampleRadius;
uniform float amzp_invertHeight;
uniform float amzp_smoothNormal;
uniform float amzp_outputMode;
uniform float amzp_lightX;
uniform float amzp_lightY;
uniform float amzp_lightZ;
layout(color) uniform half4 amzp_lightColor;
layout(color) uniform half4 amzp_ambientColor;
uniform float amzp_specular;
uniform float amzp_specPower;
uniform float amzp_ambient;
uniform float amzp_mixAmount;
    float luma(float3 c){ return dot(c,float3(0.2126,0.7152,0.0722)); }
    float4 tex(float2 uv){
      return amzTexture(0, clamp(uv,0.0,1.0));
    }
    float3 texRGB(float2 uv){ return tex(uv).rgb; }
    float3 rgb2hsv(float3 c){
      float4 K=float4(0.0,-1.0/3.0,2.0/3.0,-1.0);
      float4 p=mix(float4(c.bg,K.wz),float4(c.gb,K.xy),step(c.b,c.g));
      float4 q=mix(float4(p.xyw,c.r),float4(c.r,p.yzx),step(p.x,c.r));
      float d=q.x-min(q.w,q.y);
      return float3(abs(q.z+(q.w-q.y)/(6.0*d+1e-10)),d/(q.x+1e-10),q.x);
    }
    float getHeight(float2 uv){
      float4 c = tex(uv);
      float h;
      if(int(amzp_heightSource)==0) h = luma(c.rgb);
      else if(int(amzp_heightSource)==1) h = c.r;
      else if(int(amzp_heightSource)==2) h = c.g;
      else if(int(amzp_heightSource)==3) h = c.b;
      else if(int(amzp_heightSource)==4) h = c.a;
      else h = rgb2hsv(c.rgb).y;
      return (amzp_invertHeight>0.5) ? 1.0-h : h;
    }
    float getHeightSmooth(float2 uv, float2 ts){
      if(!(amzp_smoothNormal>0.5)) return getHeight(uv);
      float acc=0.0, ws=0.0;
      for(float x=-1.0;x<=1.0;x+=1.0){
        for(float y=-1.0;y<=1.0;y+=1.0){
          float w=exp(-(x*x+y*y)*0.5);
          acc+=getHeight(uv+float2(x,y)*ts)*w;
          ws +=w;
        }
      }
      return acc/ws;
    }
    float3 computeNormal(float2 uv){
      float2 ts = 1.0 / screen.zw * amzp_sampleRadius;
      float tl = getHeightSmooth(uv+float2(-ts.x, ts.y), ts);
      float t = getHeightSmooth(uv+float2( 0.0, ts.y), ts);
      float tr = getHeightSmooth(uv+float2( ts.x, ts.y), ts);
      float l = getHeightSmooth(uv+float2(-ts.x, 0.0), ts);
      float r = getHeightSmooth(uv+float2( ts.x, 0.0), ts);
      float bl = getHeightSmooth(uv+float2(-ts.x,-ts.y), ts);
      float b = getHeightSmooth(uv+float2( 0.0,-ts.y), ts);
      float br = getHeightSmooth(uv+float2( ts.x,-ts.y), ts);
      float dX = (-tl - 2.0*l - bl + tr + 2.0*r + br);
      float dY = (-tl - 2.0*t - tr + bl + 2.0*b + br);
      dX *= amzp_strength;
      dY *= amzp_strength;
      float3 normal = normalize(float3(-dX, dY, 1.0));
      return normal;
    }
    float3 applyLighting(float3 normal, float3 albedo){
      float3 lightDir = normalize(float3(amzp_lightX, amzp_lightY, amzp_lightZ));
      float NdL = max(dot(normal, lightDir), 0.0);
      float3 viewDir = float3(0.0, 0.0, 1.0);
      float3 halfDir = normalize(lightDir + viewDir);
      float NdH = max(dot(normal, halfDir), 0.0);
      float spec = pow(NdH, amzp_specPower) * amzp_specular;
      float3 lCol = float3(amzp_lightColor.r, amzp_lightColor.g, amzp_lightColor.b);
      float3 aCol = float3(amzp_ambientColor.r, amzp_ambientColor.g, amzp_ambientColor.b);
      float3 result = albedo * (aCol * amzp_ambient + lCol * NdL)
                  + lCol * spec;
      return clamp(result, 0.0, 1.0);
    }
    void amzRender(){
      float2 uv = amzScreenNorm();
      float4 srcTex = tex(uv);
      float3 original = srcTex.rgb / max(srcTex.a, 0.001);
      float3 normal = computeNormal(uv);
      float3 normalRGB = normal * 0.5 + 0.5;
      float2 ts = 1.0/screen.zw*amzp_sampleRadius;
      float height = getHeightSmooth(uv, ts);
      float3 heightRGB = float3(height);
      float3 result;
      if(int(amzp_outputMode) == 0){
        result = normalRGB;
      } else if(int(amzp_outputMode) == 1){
        result = applyLighting(normal, original);
      } else if(int(amzp_outputMode) == 2){
        result = heightRGB;
      } else if(int(amzp_outputMode) == 3){
        float3 lit = applyLighting(normal, original);
        result = mix(original, lit, 0.7);
        result = mix(result, normalRGB, 0.3);
      } else {
        result = applyLighting(normal, float3(0.8));
      }
      result = mix(original, result, amzp_mixAmount);
      result = clamp(result, 0.0, 1.0);
      amzOutput = float4(result, srcTex.a) * srcTex.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

